programNames.unity = 'ИИ + Unity — создаём свою игру';
export function getProjectPlan(projectId, journeyId, programId = '', gameIdeaId = '') {
  const example = demos.find(item => item.id === projectId);
  const journey = (example && findJourney(example.id)) || journeys.find(item => item.id === journeyId) || journeys[0];
  const lens = example && lenses[example.id];
  const unityMatches = programId === 'unity' && journey.id === 'story' && (!example || ['game','garder','awakening'].includes(example.id));
  // A concept is a fixed choice, never an arbitrary title supplied by the URL.
  // Existing demo links keep their identity even with stale concept context.
  const concept = unityMatches && !example ? unityGameConcepts.find(item => item.id === gameIdeaId) : null;
  return { ...journey, ...(example && overrides[example.id]), example: example || null, program: lens?.[0] || journey.program, transfer: lens?.[1] || '', ...(unityMatches ? unityPlan : {}), ...(concept ? { title: concept.title, label: `ИИ + Unity — ${concept.title}`, proposal: concept.proposal, actions: concept.actions, deliverables: concept.deliverables, checks: concept.checks, boundary: concept.boundary } : {}), concept: concept || null };
}
